<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$cot=srnu_obtener_cotizacion($id);if(!$cot){http_response_code(404);exit('Cotización no encontrada');}$dir=srnu_upload_dir('galeria');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['subir'])&&!empty($_FILES['fotos']['name'])&&is_array($_FILES['fotos']['name'])){foreach($_FILES['fotos']['name'] as $i=>$name){if($_FILES['fotos']['error'][$i]!==UPLOAD_ERR_OK||$_FILES['fotos']['size'][$i]>10*1024*1024)continue;$tmp=$_FILES['fotos']['tmp_name'][$i];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)continue;$fn='gal_'.$id.'_'.bin2hex(random_bytes(6)).'.'.$ext;if(move_uploaded_file($tmp,$dir.'/'.$fn))$pdo->prepare('INSERT INTO galeria_trabajos(cotizacion_id,etapa,archivo,descripcion,publicable) VALUES(?,?,?,?,?)')->execute([$id,epost('etapa','General'),'uploads/galeria/'.$fn,epost('descripcion'),isset($_POST['publicable'])?1:0]);}}
 if(isset($_POST['eliminar'])){$fid=(int)$_POST['foto_id'];$s=$pdo->prepare('SELECT archivo FROM galeria_trabajos WHERE id=? AND cotizacion_id=?');$s->execute([$fid,$id]);if($r=$s->fetch()){@unlink(__DIR__.'/'.$r['archivo']);$pdo->prepare('DELETE FROM galeria_trabajos WHERE id=? AND cotizacion_id=?')->execute([$fid,$id]);}}
 if(isset($_POST['toggle']))$pdo->prepare('UPDATE galeria_trabajos SET publicable=IF(publicable=1,0,1) WHERE id=? AND cotizacion_id=?')->execute([(int)$_POST['foto_id'],$id]);ego('galeria.php?id='.$id);
}
$s=$pdo->prepare('SELECT * FROM galeria_trabajos WHERE cotizacion_id=? ORDER BY id DESC');$s->execute([$id]);$rows=$s->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galería · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Galería antes / después</h1><p><?=eh($cot['folio'])?> · <?=eh($cot['cliente'])?> · <?=eh($cot['vehiculo'])?></p></div><a class="btn light" href="cotizaciones.php">← Cotizaciones</a></div><section class="panel" style="padding:18px"><form method="post" enctype="multipart/form-data" class="erp-form cols-3"><input type="hidden" name="id" value="<?=$id?>"><select name="etapa"><option>Antes</option><option>Durante</option><option>Después</option><option>General</option></select><input name="descripcion" placeholder="Descripción"><label><input type="checkbox" name="publicable"> Apta para marketing</label><input class="full" type="file" name="fotos[]" multiple accept="image/jpeg,image/png,image/webp" required><button class="btn blue" name="subir" value="1">Subir fotos</button></form></section><section class="panel" style="padding:18px;margin-top:16px"><div class="photo-grid"><?php foreach($rows as $r):?><div class="photo-card"><a target="_blank" href="galeria_foto.php?id=<?=$r['id']?>"><img src="galeria_foto.php?id=<?=$r['id']?>"></a><div><b><?=eh($r['etapa'])?></b> <?=$r['publicable']?'<span class="badge badge-green">Marketing</span>':''?><p class="muted"><?=eh($r['descripcion'])?></p><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="foto_id" value="<?=$r['id']?>"><button class="btn light" name="toggle" value="1"><?=$r['publicable']?'Quitar marketing':'Marcar marketing'?></button><button class="btn danger" name="eliminar" value="1" onclick="return confirm('¿Eliminar foto?')">Eliminar</button></form></div></div><?php endforeach;?></div></section></main></body></html>
